    (v_route, 'Landštejn', 'Zřícenina hradu. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.024, 15.23, 'http://commons.wikimedia.org/wiki/Special:FilePath/Land%C5%A1tejn%2C%202013%20%2811%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Land%C5%A1tejn%2C%202013%20%2811%29.jpg"}'::text[], 0, '{"en": {"name": "Landštejn Castle", "description": "Castle. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Landštejn", "description": "Burg in Staré Město pod Landštejnem, Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Landštejn", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Landštejn Castle", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Landštejn", "description": "Castillo en Staré Město pod Landštejnem, República Checa. Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Landštejn", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Landštejn", "description": "Замок (споруда). Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Vodní nádrž Landštejn', 'Vodní nádrž na potoce Pstruhovci. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.0236, 15.24151, 'http://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem%2C%20vodn%C3%AD%20n%C3%A1dr%C5%BE%20Land%C5%A1tejn%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem%2C%20vodn%C3%AD%20n%C3%A1dr%C5%BE%20Land%C5%A1tejn%2001.jpg"}'::text[], 1, '{"en": {"name": "Vodní nádrž Landštejn", "description": "Reservoir in Staré Město pod Landštejnem, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Vodní nádrž Landštejn", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vodní nádrž Landštejn", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Landštejn", "description": "Stuwmeer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Landštejn", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Landštejn", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vodní nádrž Landštejn", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'nový zámek Dačice', 'Zámek v Česku. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.0795, 15.4315, 'http://commons.wikimedia.org/wiki/Special:FilePath/Da%C4%8Dice%2C%20nov%C3%BD%20z%C3%A1mek.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Da%C4%8Dice%2C%20nov%C3%BD%20z%C3%A1mek.jpg"}'::text[], 2, '{"en": {"name": "Zámek Dačice", "description": "Château in Dačice I, Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schloss Datschitz", "description": "Schloss im Okres Jindřichův Hradec, Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "nový zámek Dačice", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "nový zámek Dačice", "description": "Kasteel in Dačice, Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "nový zámek Dačice", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Dačice", "description": "Château en Tchéquie. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "nový zámek Dačice", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
