    (v_route, 'Věstonická nádrž', 'Přehradní nádrž na území Dolních Věstonic. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.8978, 16.6156, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodni%20nadrz%20Nove%20Mlyny-stred.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodni%20nadrz%20Nove%20Mlyny-stred.jpg"}'::text[], 3, '{"en": {"name": "Věstonice Reservoir", "description": "Reservoir in Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Věstonická nádrž", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Věstonická nádrž", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Věstonická nádrž", "description": "Stuwmeer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Věstonická nádrž", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Věstonická nádrž", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Věstonická nádrž", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Římská vojenská pevnost u Mušova', 'Hrad na území Pasohlávek. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 48.9058, 16.5681, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mu%C5%A1ov%20-%20Roman%20fortres%20%28175-180%20AC%29%20-%20excavation.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mu%C5%A1ov%20-%20Roman%20fortres%20%28175-180%20AC%29%20-%20excavation.JPG"}'::text[], 4, '{"en": {"name": "Roman fortress in Moravia", "description": "Archaeological site in Czechia. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Římská vojenská pevnost u Mušova", "description": "Archäologische Stätte in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Římská vojenská pevnost u Mušova", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Roman fortress in Moravia", "description": "Kasteel in Pasohlávky, Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Římská vojenská pevnost u Mušova", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Římská vojenská pevnost u Mušova", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Římská vojenská pevnost u Mušova", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
