    (v_route, 'Bazilika Narození Přeblahoslavené Panny Marie', 'Kostel v Rajecké Lesné. Památka v Slovensku — kus historie přímo u trasy.', 49.0439, 18.6353, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bazilka.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bazilka.jpg"}'::text[], 2, '{"en": {"name": "Basilica of Nativity of Virgin Mary", "description": "Church building in Žilina District, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Basilika Mariä Geburt", "description": "Kirche in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Narodzenia Maryi Panny (Rajecká Lesná)", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Kerkgebouw in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika Narození Přeblahoslavené Panny Marie", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kľacký vodopád', 'Národní přírodní památka na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.9825, 18.65556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Klacky%20vodopad.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Klacky%20vodopad.jpg"}'::text[], 3, '{"en": {"name": "Kľacký vodopád", "description": "National natural monument in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Kľacký vodopád", "description": "Wasserfall in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Kľacký vodopád", "description": "Wodospad na Słowacji. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kľacký vodopád", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Klacky vodopad", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Kľacký vodopád", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Kľacký vodopád", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Starý hrad', 'Zřícenina hradu na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 49.17778, 18.89028, 'http://commons.wikimedia.org/wiki/Special:FilePath/Starhrad%20detail.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Starhrad%20detail.jpg"}'::text[], 4, '{"en": {"name": "Starhrad", "description": "Castle in Slovakia. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Starý hrad", "description": "Ruinen von Starý hrad in der nördlichen Slowakei in der Kleinen Fatra, unweit der Gemeinde Nezbudská Lúčka. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Starý hrad", "description": "Zamek w północnej Słowacji,. Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Starý hrad", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Starý hrad", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Starý hrad", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Starý hrad", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
