    (v_route, 'Vodní nádrž Krpeľany', 'Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.13433, 19.09192, 'http://commons.wikimedia.org/wiki/Special:FilePath/Krpe%C4%BEany10.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Krpe%C4%BEany10.JPG"}'::text[], 6, '{"en": {"name": "Krpeľany Reservoir", "description": "A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Krpeľany", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Krpeľany (zbiornik wodny)", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Krpeľany", "description": "Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Krpeľany", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Krpeľany", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Крпеляни (водосховище)", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
