    (v_route, 'Cathedral Basilica of the Assumption, Pelplin', 'Památka v Polsku — kus historie přímo u trasy.', 53.92745, 18.69429, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pelplin%20bazylika.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pelplin%20bazylika.JPG"}'::text[], 0, '{"en": {"name": "Cathedral Basilica of the Assumption, Pelplin", "description": "Church in Pelplin, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kloster Pelplin", "description": "Kloster in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Katedralna Wniebowzięcia Najświętszej Maryi Panny w Pelplinie", "description": "Świątynia katolicka. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster Pelplin", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Basílica de la Asunción de la Virgen María", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Assomption", "description": "Édifice religieux situé à Pelplin, en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Cathedral Basilica of the Assumption, Pelplin", "description": "Церква в Польщі. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Gniew Castle', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 53.83433, 18.82801, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20w%20Gniewie%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20w%20Gniewie%201.jpg"}'::text[], 1, '{"en": {"name": "Gniew Castle", "description": "Castle in Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Burg Mewe", "description": "Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Gniewie", "description": "Zamek zbudowany przez zakon krzyżacki w latach 1290 - 1330. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Gniew Castle", "description": "Kasteel in Gniew, Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Gniew Castle", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Gniew", "description": "Château en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Gniew Castle", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
