    (v_route, 'Smocza Jama', 'Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 50.05311, 19.93358, 'http://commons.wikimedia.org/wiki/Special:FilePath/Krak%C3%B3w%20-%20Wawel%20-%20Smocza%20Jama%20-%20inside.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Krak%C3%B3w%20-%20Wawel%20-%20Smocza%20Jama%20-%20inside.jpg"}'::text[], 2, '{"en": {"name": "Smocza Jama", "description": "Limestone cave in the Wawel Hill in Kraków. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Smocza Jama", "description": "Höhle im Wawelhügel in Krakau, Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Smocza Jama", "description": "Jaskinia w Krakowie. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Smocza Jama", "description": "Nationaal monument in Krakau, Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Smocza Jama (Cracovia)", "description": "Cueva en el cerro de Wawel, Polonia. Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Smocza Jama", "description": "Grotte en Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Smocza Jama", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
