    (v_route, 'Żupny Castle', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 49.9839, 20.0597, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%2C%20v%C4%9B%C5%BE%20a%20ze%C4%8F.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wieliczka%2C%20v%C4%9B%C5%BE%20a%20ze%C4%8F.JPG"}'::text[], 4, '{"en": {"name": "Żupny Castle", "description": "Castle in Wieliczka, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Salzgrafenschloss Wieliczka", "description": "Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Żupny", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Żupny Castle", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Żupny Castle", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Żupny", "description": "Château de Wieliczka, Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Жупни", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
