    (v_route, 'Vodní nádrž Šance', 'Vodní nádrž na řece Ostravici. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.51028, 18.41583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%A0ance%20l%C3%A9to%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%A0ance%20l%C3%A9to%20%281%29.jpg"}'::text[], 0, '{"en": {"name": "Šance Reservoir", "description": "Body of water. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Vodní nádrž Šance", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zbiornik wodny Šance", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Šance", "description": "Stuwmeer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Presa de Šance", "description": "Presa de República Checa. Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Barrage de Šance", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Шанце", "description": "Водний об''єкт. Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Kněhyně – Čertův mlýn', 'Národní přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.49278, 18.305, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kn%C4%9Bhyn%C4%9B%20%28vlevo%29%20a%20%C4%8Cert%C5%AFv%20ml%C3%BDn%20%28z%20Pusteven%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kn%C4%9Bhyn%C4%9B%20%28vlevo%29%20a%20%C4%8Cert%C5%AFv%20ml%C3%BDn%20%28z%20Pusteven%29.JPG"}'::text[], 1, '{"en": {"name": "Kněhyně - Čertův mlýn", "description": "National nature reserve in the Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Kněhyně-Čertův mlýn", "description": "Nationales Naturreservat im Osten Tschechiens. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Narodowy rezerwat przyrody Kněhyně - Čertův mlýn", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kněhyně – Čertův mlýn", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Kněhyně - Čertův mlýn", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Kněhyně – Čertův mlýn", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Kněhyně – Čertův mlýn", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
