    (v_route, 'Otmuchovské jezero', 'Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.4633, 17.1222, 'http://commons.wikimedia.org/wiki/Special:FilePath/2014%20Jezioro%20Otmuchowskie%20w%20%C5%9Aciborzu.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2014%20Jezioro%20Otmuchowskie%20w%20%C5%9Aciborzu.JPG"}'::text[], 0, '{"en": {"name": "Otmuchów Lake", "description": "Lake. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Jezioro Otmuchowskie", "description": "Stausee in Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Otmuchowskie", "description": "Zbiornik retencyjny w południowej Polsce. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Otmuchów Lake", "description": "Stuwmeer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Otmuchovské jezero", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Otmuchovské jezero", "description": "Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Otmuchovské jezero", "description": "Озеро. Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
