    (v_route, 'vodní nádrž Klíčava', 'Vodní nádrž na Klíčavě v Česku. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.0644, 13.9339, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Kl%C3%AD%C4%8Dava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Kl%C3%AD%C4%8Dava.jpg"}'::text[], 5, '{"en": {"name": "Klíčava water reservoir", "description": "Reservoir in Zbečno, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "vodní nádrž Klíčava", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Klíčava", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Klíčava", "description": "Stuwmeer in Zbečno, Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Klíčava", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Klíčava", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Klíčava", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
