    (v_route, 'Zámek Kynžvart', 'Zámek v západních Čechách. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.00431, 12.60558, 'http://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Kyn%C5%BEvart%20celek%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Kyn%C5%BEvart%20celek%201.jpg"}'::text[], 0, '{"en": {"name": "Castle Kynžvart", "description": "Castle in Kynžvart, Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schloss Königswart", "description": "Schloss in Tschechien, ehemals Sitz der Familie Metternich. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zámek Kynžvart", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "slot Kynžvart", "description": "Slot in de Tsjechische stad Lázně Kynžvart. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Zámek Kynžvart", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Kynžvart", "description": "Château et musée tchèque. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Zámek Kynžvart", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'vodní nádrž Jesenice', 'Přehrada na Odravě v okrese Cheb. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.0628, 12.4517, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Jesenice%2C%20star%C3%BD%20most%20ve%20vod%C4%9B.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Jesenice%2C%20star%C3%BD%20most%20ve%20vod%C4%9B.JPG"}'::text[], 1, '{"en": {"name": "Jesenice Reservoir", "description": "Lake in Cheb, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Jesenice", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Jesenice", "description": "Zbiornik retencyjny (Cheb, Czechy). Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Jesenice", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Jesenice", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Jesenice", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Jesenice", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
