    (v_route, 'vodní nádrž Skalka', 'Vodní nádrž na Ohři v Chebu. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.07915, 12.3536, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cheb%20Skalka%20reservoir%202009-08-06.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cheb%20Skalka%20reservoir%202009-08-06.jpg"}'::text[], 3, '{"en": {"name": "Údolní nádrž Skalka", "description": "Lake in Cheb, Karlovy Vary Region, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Skalka", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Skalka", "description": "Zbiornik retencyjny (Cheb, Czechy). Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Skalka", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Skalka", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Skalka", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Skalka", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Seeberg', 'Hrad v Česku. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.1319, 12.2823, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Seeberg%20duben%202019%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Seeberg%20duben%202019%20%281%29.jpg"}'::text[], 4, '{"en": {"name": "Seeberg", "description": "Castle. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Seeberg", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Seeberg", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burg Seeberg", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Seeberg", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Seeberg", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Seeberg", "description": "Замок (споруда). Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Hartenberg', 'Hrad přestavěný na zámek. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.22172, 12.57551, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hartenberg%20castel%20H%C5%99ebeny%202010-08-21%20%2803%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hartenberg%20castel%20H%C5%99ebeny%202010-08-21%20%2803%29.jpg"}'::text[], 5, '{"en": {"name": "Hartenberg", "description": "Medieval castle, ruin of a chateau. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Schlossruine Hartenberg", "description": "Schloss in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Hartenberg", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hartenberg", "description": "Kasteel in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Hartenberg", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Hartenberg", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Hartenberg", "description": "Замок у Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Kanonie premonstrátů klášter Teplá', 'Premonstrátský klášter a opatství v západních Čechách. Památka v Česku — kus historie přímo u trasy.', 49.96639, 12.87833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kl%20Tepl%C3%A1%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kl%20Tepl%C3%A1%201.jpg"}'::text[], 6, '{"en": {"name": "Teplá Abbey", "description": "National monument of the Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Stift Tepl", "description": "Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kanonie premonstrátů klášter Teplá", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster van Teplá", "description": "Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Kanonie premonstrátů klášter Teplá", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Teplá", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kanonie premonstrátů klášter Teplá", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Pavlova Huť', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.78361, 12.46528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pavlova%20Hu%C5%A5%20Nature%20Reserve%20%28CZE%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pavlova%20Hu%C5%A5%20Nature%20Reserve%20%28CZE%29.jpg"}'::text[], 7, '{"en": {"name": "Pavlova Huť Nature Reserve", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Pavlova Huť (Naturschutzgebiet)", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Pavlova Huť", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Pavlova Huť", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Pavlova Huť", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Pavlova Huť", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Pavlova Huť", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb);
