    (v_route, 'Sloupsko-šošůvské jeskyně', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.4114, 16.739, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sloupsko-%C5%A1o%C5%A1%C5%AFvsk%C3%A9-jeskyn%C4%9B-interi%C3%A9r2018Eli%C5%A1%C4%8Dina-jeskyn%C4%9B5.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sloupsko-%C5%A1o%C5%A1%C5%AFvsk%C3%A9-jeskyn%C4%9B-interi%C3%A9r2018Eli%C5%A1%C4%8Dina-jeskyn%C4%9B5.jpg"}'::text[], 6, '{"en": {"name": "Sloupsko-šošůvské jeskyně", "description": "Nature reserve. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Sloupsko-šošůvské jeskyně", "description": "Höhlensystem in Tschechien. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Jaskinie Sloupsko-šošůvské", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Sloupsko-šošůvské jeskyně", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Sloupsko-šošůvské jeskyně", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Sloupsko-šošůvské jeskyně", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Sloupsko-šošůvské jeskyně", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
