    (v_route, 'Katedrální bazilika Nanebevzetí Nejsvětější Panny Marie ve Włocławku', 'Památka v Polsku — kus historie přímo u trasy.', 52.66107, 19.06796, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20katedralna%20WNMP%20we%20W%C5%82oc%C5%82awku%20%28cropped%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20katedralna%20WNMP%20we%20W%C5%82oc%C5%82awku%20%28cropped%29.jpg"}'::text[], 0, '{"en": {"name": "Basilica Cathedral of St. Mary of the Assumption", "description": "Church building in Włocławek, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kathedrale von Włocławek", "description": "Kirchengebäude in der Woiwodschaft Kujawien-Pommern, Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Katedralna Wniebowzięcia Najświętszej Maryi Panny we Włocławku", "description": "Świątynia katolicka. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Katedrální bazilika Nanebevzetí Nejsvětější Panny Marie ve Włocławku", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Basílica de la Asunción de la Virgen María", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Assomption", "description": "Édifice religieux situé à Włocławek, en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrální bazilika Nanebevzetí Nejsvětější Panny Marie ve Włocławku", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
